  }

  /** Validates `input` against the registered `inputSchema`, returning a rejection `ToolResponse` for schema failures (specs/hal-engine-tool-input-validation/spec.md); throws only for an unknown tool name. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
