import {createRequire} from 'node:module';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

// ajv is CommonJS, so it is required through createRequire: an ESM named import of it does not
// survive every runtime this package is loaded under.
const nodeRequire = createRequire(import.meta.url);

// The two shapes the engine reads are stable across the ajv majors that ship these fields.
interface SchemaError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  message?: string;
  params?: {missingProperty?: unknown; type?: unknown; allowedValues?: unknown};
}

interface CompiledSchema {
  (data: unknown): boolean;
  errors: SchemaError[] | null;
}

interface SchemaCompiler {
  compile(schema: object): CompiledSchema;
}

// Schemas reach the engine shaped for the providers, so validation accepts what they accept rather than tightening it.
const schemaValidationOptions = {strict: false, validateFormats: false};

const {Ajv} = nodeRequire('ajv') as {Ajv: new (options: typeof schemaValidationOptions) => SchemaCompiler};

// ajv 8 writes JSON pointer paths (`instancePath`); 6 wrote dotted ones (`dataPath`).
function propertyPathOf(error: SchemaError): string {
  return (error.instancePath ?? error.dataPath ?? '').split(/[./]/).filter(Boolean).join('.');
}

// Names the property path and the constraint that failed; never the value.
function describeSchemaError(error: SchemaError): string {
  const path = propertyPathOf(error);
  const where = path.length > 0 ? `${path} ` : '';
  if (error.keyword === 'required') return `${where}${String(error.params?.missingProperty)} is required`;
  if (error.keyword === 'type') return `${where}must be of type ${String(error.params?.type)}`;
  if (error.keyword === 'enum') return `${where}must be one of ${JSON.stringify(error.params?.allowedValues)}`;
  return `${where}${error.message ?? 'is invalid'}`;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv(schemaValidationOptions);
  // Keyed by schema object, so a function-valued source returning a new schema compiles fresh.
  private readonly validators = new WeakMap<object, CompiledSchema>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(name: string, schema: object): CompiledSchema {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    let compiled: CompiledSchema;
    try {
      compiled = this.schemaValidator.compile(schema);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(`Tool ${name} has an invalid inputSchema: ${detail}`, {cause: error});
    }
    this.validators.set(schema, compiled);
    return compiled;
  }

  private rejectionFor(definition: ToolDefinition, input: Record<string, unknown>): ToolResponse | undefined {
    const validate = this.validatorFor(definition.name, definition.inputSchema);
    if (validate(input)) return undefined;
    const reason = (validate.errors ?? []).map(describeSchemaError).join('; ');
    log.warn('tool', 'tool input rejected', {name: definition.name, reason});
    return {result: `Invalid input for tool ${definition.name}: ${reason}`};
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    // A static schema compiles here, so a broken one fails at startup rather than mid-conversation.
    if (typeof definition !== 'function') this.validatorFor(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates `input` against the registered `inputSchema`, returning a rejection `ToolResponse` for schema failures (specs/hal-engine-tool-input-validation/spec.md); throws only for an unknown tool name. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const rejection = this.rejectionFor(definition, input);
    if (rejection) return rejection;
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

